// Normalise Polymarket's Gamma response into `markets` + `bands` rows.
//
// THIS NODE TOOK AN n8n INSTANCE DOWN. It read the payload like this:
//
//     const raw    = $('Fetch markets').all().map(i => i.json).flat();   // copy 1
//     const events = []; for (...) events.push(...item);                 // copy 2
//
// Two full copies of the response, held alongside n8n's own copy, while the
// output was built. Against a Gamma /events?limit=200 response - which can be
// 80-90 MB when the events are not actually weather events - that is a quarter
// of a gigabyte in one Code node. The process ran out of memory and restarted,
// which reaches the operator as "workspace offline, 503".
//
// It now walks the payload ONCE, keeps only the six small fields it needs from
// each event, and stops at max_events. Peak memory is proportional to what is
// KEPT, not to what arrived. The caps are in Config and every one of them is
// enforced here rather than trusted to the URL.
//
// THE SHAPE THIS EXPECTS. A Polymarket temperature market is an EVENT (one
// city, one day) containing one BINARY MARKET PER BUCKET:
//
//     event            -> one row in `markets`
//     event.markets[]  -> one row in `bands`
//
// THE PART THAT MATTERS MOST: band_lo / band_hi. Polymarket states the bucket
// in TEXT ("70-71F", "78F or above"), and the probability lattice, every edge
// and band_contains() in ad4_34 all need the numeric interval. A band with null
// bounds cannot be priced, so the parse counts its failures and the guard
// refuses a run where most of them failed.
//
// Intervals are HALF-OPEN [lo, hi), matching sql/ad4_34's band_contains().
// "70-71F" settles on an integer high of 70 or 71, so it is [70, 72).

const cfg       = $('Config').first().json;
const MAX_EVENTS = Math.max(1, Number(cfg.max_events || 40));
const MAX_BANDS  = Math.max(1, Number(cfg.max_bands || 800));

const cities = $('Load cities').all().map(i => i.json);

// ---- deterministic ids ----------------------------------------------------
// markets.market_id and bands.band_id are uuid columns, and Polymarket's own
// ids are numeric strings and 0x hex - neither is a uuid. They must also be
// STABLE across runs or every run inserts duplicates instead of upserting.
// So: a hash of the natural key, formatted as a uuid. Same input, same id.
function uuidFrom(str) {
  const s = String(str);
  let h = '';
  for (let salt = 0; salt < 4; salt++) {
    let v = 0x811c9dc5 ^ salt;
    for (let i = 0; i < s.length; i++) {
      v ^= s.charCodeAt(i);
      v = Math.imul(v, 0x01000193) >>> 0;
    }
    h += v.toString(16).padStart(8, '0');
  }
  return [h.slice(0, 8), h.slice(8, 12), '4' + h.slice(13, 16),
          ((parseInt(h[16], 16) & 0x3 | 0x8).toString(16)) + h.slice(17, 20),
          h.slice(20, 32)].join('-');
}

// ---- the bucket text ------------------------------------------------------
// Returns {lo, hi, open_low, open_high} or null when the text cannot be read.
function parseBucket(text) {
  if (!text) return null;
  const t = String(text).replace(/[°℉℃]/g, ' ')
                        .replace(/[–—]/g, '-')
                        .toLowerCase()
                        // "59 F or below" -> "59 or below". The unit letter is
                        // left behind by stripping the degree sign and breaks
                        // every pattern that expects a number then a word.
                        .replace(/(\d)\s*[fc](?![a-z])/g, '$1')
                        .replace(/\s+/g, ' ')
                        .trim();

  const num = '(-?\\d+(?:\\.\\d+)?)';

  // "70-71", "70 to 71"
  let m = t.match(new RegExp('^' + num + '\\s*(?:-|to)\\s*' + num));
  if (m) {
    const lo = parseFloat(m[1]), hiLabel = parseFloat(m[2]);
    // Integer buckets are inclusive of both ends, so the half-open upper bound
    // is one step past the label. A fractional label is already continuous.
    const step = Number.isInteger(lo) && Number.isInteger(hiLabel) ? 1 : 0;
    return { lo, hi: hiLabel + step, open_low: false, open_high: false };
  }

  // "78 or above", "78+", "above 78", "at least 78"
  m = t.match(new RegExp('^' + num + '\\s*(?:\\+|or (?:above|higher|more)|and (?:above|up|higher))'))
      || t.match(new RegExp('^(?:above|over|at least|greater than)\\s*' + num));
  if (m) return { lo: parseFloat(m[1]), hi: null, open_low: false, open_high: true };

  // "59 or below", "below 60", "under 60", "less than 60"
  m = t.match(new RegExp('^' + num + '\\s*(?:-|or (?:below|less|lower|fewer))'))
      || t.match(new RegExp('^(?:below|under|less than|at most)\\s*' + num));
  if (m) {
    const v = parseFloat(m[1]);
    // "59 or below" includes 59, so the exclusive bound is 60. "below 60" is
    // already exclusive.
    const inclusive = /or (below|less|lower|fewer)/.test(t);
    return { lo: null, hi: inclusive ? v + 1 : v, open_low: true, open_high: false };
  }

  // A bare number: a single-degree bucket.
  m = t.match(new RegExp('^' + num + '\\s*$'));
  if (m) {
    const v = parseFloat(m[1]);
    return { lo: v, hi: Number.isInteger(v) ? v + 1 : v, open_low: false, open_high: false };
  }

  return null;
}

// ---- which day does this market settle on? --------------------------------
// Gamma gives endDate, and for a US market that is typically 04:00-05:00 UTC on
// the day AFTER the local trading day. Rolling an early-UTC end time back one
// day recovers the local day. Stated as a rule rather than buried, because
// getting it wrong shifts every market by a day and nothing downstream can
// tell: check the dates the Summary node prints on your first run.
function resolutionDate(ev) {
  const iso = ev.endDate || ev.end_date || ev.endDateIso || null;
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  if (d.getUTCHours() < 12) d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

function tokensOf(mk) {
  // clobTokenIds arrives as a JSON STRING, not an array.
  let raw = mk.clobTokenIds ?? mk.clob_token_ids ?? mk.tokens ?? null;
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw); } catch { raw = null; }
  }
  if (!Array.isArray(raw)) return [null, null];
  const norm = raw.map(t => (t && typeof t === 'object') ? (t.token_id ?? t.tokenId ?? null) : t);
  return [norm[0] ?? null, norm[1] ?? null];
}

/** Match an event to one of our cities on its slug or title. */
function cityFor(hay) {
  for (const c of cities) {
    if (!c || !c.city_key) continue;
    const k = String(c.city_key).toLowerCase();
    if (hay.includes(k)) return c;
    if (c.icao && hay.includes(String(c.icao).toLowerCase())) return c;
    if (c.display_name && hay.includes(String(c.display_name).toLowerCase().replace(/\s+/g, '-'))) return c;
  }
  return null;
}

// ---- walk it ONCE ---------------------------------------------------------
const markets = [], bands = [];
let nEvents = 0, skippedNoCity = 0, bandParseFailed = 0, capped = false;
const failedLabels = [];
const datesSeen = new Set();

/** Handle one event. Returns false when a cap has been reached. */
function takeEvent(ev) {
  if (!ev || typeof ev !== 'object') return true;
  nEvents++;
  if (markets.length >= MAX_EVENTS || bands.length >= MAX_BANDS) { capped = true; return false; }

  const slug  = String(ev.slug || ev.event_slug || '');
  const title = String(ev.title || ev.question || '');
  const city  = cityFor((slug + ' ' + title).toLowerCase());
  if (!city) { skippedNoCity++; return true; }

  const inner = Array.isArray(ev.markets) ? ev.markets
              : (Array.isArray(ev.outcomes) ? ev.outcomes : []);
  if (inner.length === 0) return true;

  const forDate = resolutionDate(ev);
  if (forDate) datesSeen.add(forDate);
  const marketId = uuidFrom('ad4:market:' + (slug || ev.id));
  const before = bands.length;

  for (let idx = 0; idx < inner.length; idx++) {
    if (bands.length >= MAX_BANDS) { capped = true; break; }
    const mk = inner[idx];
    if (!mk) continue;
    const label = mk.groupItemTitle || mk.group_item_title || mk.outcome ||
                  mk.band_label || mk.label || mk.question || '';
    const b = parseBucket(label) ||
              // Fall back to the tail of the question: "... be 70-71F?"
              parseBucket(String(mk.question || '').replace(/^.*\bbe\b\s*/i, '').replace(/\?\s*$/, ''));
    if (!b) {
      bandParseFailed++;
      if (failedLabels.length < 5) failedLabels.push(String(label).slice(0, 60));
      continue;                                 // no bounds means it cannot be priced
    }
    const [yes, no] = tokensOf(mk);
    bands.push({
      band_id: uuidFrom('ad4:band:' + (mk.conditionId || mk.condition_id || (slug + ':' + idx))),
      market_id: marketId,
      band_index: idx,
      band_label: String(label).trim() || null,
      band_lo: b.lo, band_hi: b.hi,
      open_low: b.open_low, open_high: b.open_high,
      condition_id: mk.conditionId || mk.condition_id || null,
      token_yes: yes, token_no: no,
    });
  }

  if (bands.length === before) return true;     // nothing priceable in this event
  markets.push({
    market_id: marketId,
    city_key: city.city_key,
    resolution_date: forDate,
    event_slug: slug || null,
    title: title || null,
    unit: city.unit || 'C',
    band_count: bands.length - before,
    closed: Boolean(ev.closed),
    condition_id: ev.conditionId || ev.condition_id || null,
    last_seen_at: new Date().toISOString(),
  });
  return true;
}

// The payload may be a bare array of events, {data:[...]}, {events:[...]}, or a
// single event - and n8n may already have split an array response into items.
// Each shape is walked in place; nothing is concatenated into a second array.
outer:
for (const item of $('Fetch markets').all()) {
  const j = item.json;
  if (!j) continue;
  const list = Array.isArray(j) ? j
             : (Array.isArray(j.data) ? j.data
             : (Array.isArray(j.events) ? j.events : null));
  if (list) {
    for (const ev of list) if (!takeEvent(ev)) break outer;
  } else {
    if (!takeEvent(j)) break outer;
  }
}

// Order the bands within each market by their floor, so band_index is the
// ladder position rather than the order Polymarket happened to list them.
const byMarket = {};
for (const b of bands) (byMarket[b.market_id] = byMarket[b.market_id] || []).push(b);
for (const list of Object.values(byMarket)) {
  list.sort((x, y) => (x.band_lo ?? -1e9) - (y.band_lo ?? -1e9));
  list.forEach((b, i) => { b.band_index = i; });
}
// band_count is what the desk can actually PRICE, not what Polymarket listed.
// The overround check sums a ladder and reads a short one as a cheap book.
for (const m of markets) m.band_count = (byMarket[m.market_id] || []).length;

return [{ json: {
  markets, bands,
  n_markets: markets.length,
  n_bands: bands.length,
  n_events: nEvents,
  skipped_no_city: skippedNoCity,
  band_parse_failed: bandParseFailed,
  failed_labels: failedLabels,
  dates: Array.from(datesSeen).sort(),
  capped,
  max_events: MAX_EVENTS,
  n_raw: nEvents,
} }];

const p = $('Parse markets + bands').first().json;

if (p.n_markets === 0) {
  throw new Error(
    `Parsed 0 markets from ${p.n_events} event(s) ` +
    `(${p.skipped_no_city} skipped: the slug matched none of your city keys). ` +
    `Nothing was written. Two likely causes, in order: the tag_slug filter on ` +
    `markets_url no longer matches Polymarket's weather tag - drop it and use ` +
    `https://gamma-api.polymarket.com/events?closed=false&limit=500 - or your ` +
    `cities table uses keys that do not appear in the slugs, in which case set ` +
    `cities.display_name to the name Polymarket uses.`);
}

// A BAND WITH NO NUMERIC BOUNDS CANNOT BE PRICED. Not by the probability
// lattice, not by any edge, not by band_contains() in ad4_34. Writing a ladder
// with holes in it is worse than writing nothing: the overround check reads it
// as a cheap book and every coverage figure computed from it is wrong.
//
// A few failures are normal - a market can carry a non-temperature outcome.
// Most of them failing means the label format moved, and the run stops.
const attempted = (p.n_bands || 0) + (p.band_parse_failed || 0);
if (attempted > 0 && p.band_parse_failed > attempted / 2) {
  throw new Error(
    `${p.band_parse_failed} of ${attempted} buckets had a label this workflow ` +
    `could not read, so their bounds would be null and nothing downstream can ` +
    `price them. Nothing was written. Labels it choked on: ` +
    `${(p.failed_labels || []).join(' | ')}. Fix parseBucket() in ` +
    `"Parse markets + bands" - the patterns are at the top of the node.`);
}

return [{ json: p }];

// DID THE DATABASE ACTUALLY TAKE IT?
//
// Every write node here carries onError=continueRegularOutput, so the workflow
// walks straight past a rejected write and reaches this node looking healthy.
// That is how a run reports success having written nothing - which is exactly
// what happened: reads worked, every write was refused, and the only visible
// error was on the LAST node in the chain.
//
// With neverError on, a refusal arrives as the PostgREST error body instead of
// an exception, so it can be read and named here.
function writeError(node) {
  let items;
  try { items = $(node).all(); } catch (e) { return null; }
  for (const it of items || []) {
    const b = it && it.json;
    if (!b || typeof b !== 'object') continue;
    if (b.error && !b.code) return { node, code: null, message: String(b.error).slice(0, 300) };
    if (b.code || b.message) {
      return { node, code: b.code ?? null,
               message: b.message ?? '', details: b.details ?? null, hint: b.hint ?? null };
    }
  }
  return null;
}

const WRITE_NODES = ["Upsert markets", "Upsert bands"];
for (const node of WRITE_NODES) {
  const e = writeError(node);
  if (!e) continue;
  // 42501 is the one worth naming, because the cause is never the code.
  if (String(e.code) === '42501' || /permission denied/i.test(e.message)) {
    throw new Error(
      `Supabase REFUSED the write: ${e.message} (${e.code}). This is the ANON key in the ` +
      `Config node, not the service key - anon is granted SELECT and nothing else, which is ` +
      `why reads worked and every write was silently dropped. Open Config -> service_key and ` +
      `paste the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
      `key beginning sb_secret_). NEVER put that key anywhere starting NEXT_PUBLIC_. ` +
      `Failing node: ${e.node}. Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write at "${e.node}": ${e.message}` +
    (e.code ? ` (${e.code})` : '') + (e.details ? ` - ${e.details}` : '') +
    (e.hint ? ` Hint: ${e.hint}` : '') + ' Nothing was written.');
}

const p = $('Parse markets + bands').first().json;
const rows = (p.n_markets || 0) + (p.n_bands || 0);
const failed = p.band_parse_failed || 0;

// CHECK THESE TWO ON THE FIRST RUN. The dates come from endDate rolled back a
// day when it lands before noon UTC; if they are all one day out, that rule is
// what to change. The unreadable labels are the other half - a handful is
// normal, a pile means the format moved.
const summary =
  `AD4 P0.2: ${p.n_markets} market(s), ${p.n_bands} band(s) upserted from ` +
  `${p.n_events} event(s). Settlement dates: ${(p.dates || []).join(', ') || 'none'}. ` +
  `${p.skipped_no_city} event(s) matched no city` +
  (failed ? `. ${failed} bucket label(s) unreadable: ${(p.failed_labels || []).join(' | ')}` : '') + '.';

const status = rows > 0 ? (failed ? 'attention' : 'ok') : 'attention';
const detail = { n_markets: p.n_markets, n_bands: p.n_bands, n_events: p.n_events,
                 skipped_no_city: p.skipped_no_city, band_parse_failed: failed,
                 failed_labels: p.failed_labels || [], dates: p.dates || [] };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P0.2_market_discovery', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];

// AN ENDPOINT THIS FILE CANNOT KNOW.
//
// P0.2-P0.5 are RECONSTRUCTIONS. The Supabase half is grounded in the real
// schema and is safe; the Polymarket half never was. These files used to ship
// with a plausible-looking URL already filled in, which is worse than shipping
// none: it reads as authoritative, so nobody changes it, and the run dies four
// nodes later with a message about response shapes. That is exactly how this
// wasted an afternoon.
//
// So the field ships EMPTY and the run stops here - before any HTTP call,
// before any database read - saying where the real value is.
{
  const cfg = $('Config').first().json ?? {};
  const missing = Object.keys(cfg)
    .filter((k) => k.endsWith('_url') && k !== 'supabase_url')
    .filter((k) => !String(cfg[k] ?? '').trim());
  if (missing.length) {
    throw new Error(
      `Config.${missing.join(' and Config.')} is empty, and this file cannot fill it in. ` +
      `Open your OWN working P0.2-P0.5 in n8n, click its Polymarket HTTP node, copy the URL ` +
      `from it, and paste it here. Those workflows are what put 841 markets and 122,000 trades ` +
      `in this database - they are the authority on the endpoint, not this reconstruction. ` +
      `Nothing was fetched and nothing was written.`);
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot call should_run, and a key that cannot do that cannot write either -
// so stop, rather than failing open into a run that writes nothing.
//
// THIS IS NOT THE MAIN DEFENCE AND MUST NOT BE MISTAKEN FOR IT. sql/ad4_20
// grants should_run to anon ON PURPOSE, so the Workflows page can preview a
// schedule change before saving it. On a database with that grant - which is
// every database that ran ad4_20 - an anon key sails straight through this
// check and only fails at the first WRITE. The write guard in the Summary
// node is what actually catches it; run section 6 of sql/ad4_diagnose.sql to
// see which key can write what before spending a run finding out.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). This is the ANON ` +
    `key in the Config node, not the service key - anon is granted SELECT and nothing else. ` +
    `Every write in this workflow would be refused the same way. Open Config -> service_key ` +
    `and paste the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or ` +
    `a key beginning sb_secret_). NEVER put that key anywhere starting NEXT_PUBLIC_.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;

// IS THIS A WEATHER RESPONSE AT ALL?
//
// The first version of this workflow shipped `tag_slug=weather` on the Gamma
// URL. Gamma IGNORES query parameters it does not recognise - it does not
// reject them - so the request quietly became "give me 200 open events, any
// topic": elections, sports, each with hundreds of nested markets and
// multi-kilobyte descriptions. Eighty megabytes of JSON, which n8n then holds
// as one node's output, again as the next node's input, and serialises into
// its execution store. On a small instance that is an out-of-memory, and it
// reaches the operator as "workspace offline, 503".
//
// This measures what came back before anything else touches it, and stops with
// a message naming the cause rather than letting the run grind the instance
// down.

const cfg   = $('Config').first().json;
const items = $('Fetch markets').all();
const cities = $('Load cities').all().map(i => i.json);

const MAX_MB = Math.max(1, Number(cfg.max_response_mb || 12));

let bytes = 0, nEvents = 0, matched = 0;
for (const it of items) {
  const j = it.json;
  if (!j) continue;
  const list = Array.isArray(j) ? j
             : (Array.isArray(j.data) ? j.data : (Array.isArray(j.events) ? j.events : [j]));
  nEvents += list.length;
  for (const ev of list) {
    if (!ev) continue;
    const hay = (String(ev.slug || '') + ' ' + String(ev.title || '')).toLowerCase();
    if (cities.some(c => c && c.city_key && (
          hay.includes(String(c.city_key).toLowerCase()) ||
          (c.display_name && hay.includes(String(c.display_name).toLowerCase().replace(/\s+/g, '-')))))) {
      matched++;
    }
  }
}
// Measure once, on the raw items, rather than per event.
try { bytes = JSON.stringify(items.map(i => i.json)).length; } catch { bytes = 0; }
const mb = bytes / 1024 / 1024;

if (mb > MAX_MB && matched === 0) {
  throw new Error(
    `Polymarket returned ${mb.toFixed(0)} MB across ${nEvents} event(s) and NOT ONE matched a city ` +
    `in your cities table. This is an unfiltered feed, not the weather markets, and carrying it ` +
    `further is what takes n8n offline with a 503. Nothing was fetched from Supabase and nothing ` +
    `was written. Narrow markets_url in Config - lower its limit, or add a filter that Gamma ` +
    `actually honours - then run again. Cap: max_response_mb = ${MAX_MB}.`);
}
if (mb > MAX_MB) {
  throw new Error(
    `Polymarket returned ${mb.toFixed(0)} MB, over the ${MAX_MB} MB cap, from ${nEvents} event(s) ` +
    `(${matched} matched a city). n8n holds a payload this size several times over in one run and ` +
    `serialises it into its execution store, which is what takes the instance offline. Nothing was ` +
    `written. Lower the limit= on markets_url in Config, or raise max_response_mb if your instance ` +
    `has the memory for it.`);
}

return [{ json: { response_mb: Number(mb.toFixed(2)), n_events: nEvents, matched_a_city: matched } }];
